from typing import Protocol


class RangeTransformer(Protocol):
    def covered_tiles(
        self,
        *,
        origin: tuple[int, int],
        offsets: tuple[tuple[int, int], ...],
        direction: str,
    ) -> set[tuple[int, int]]:
        """Convert canonical range offsets into map tiles for one facing direction."""


class CanonicalSyntheticRangeTransformer:
    """Synthetic-only orientation rule; it makes no claim about Arknights' rule.

    Offsets are defined for RIGHT. RIGHT=(dx,dy), DOWN=(-dy,dx), LEFT=(-dx,-dy),
    and UP=(dy,-dx), with x increasing right and y increasing down.
    """

    _directions = {"RIGHT", "DOWN", "LEFT", "UP"}

    def covered_tiles(
        self,
        *,
        origin: tuple[int, int],
        offsets: tuple[tuple[int, int], ...],
        direction: str,
    ) -> set[tuple[int, int]]:
        if direction not in self._directions:
            raise ValueError(f"Unsupported synthetic direction: {direction}")
        def rotate(dx: int, dy: int) -> tuple[int, int]:
            if direction == "RIGHT": return dx, dy
            if direction == "DOWN": return -dy, dx
            if direction == "LEFT": return -dx, -dy
            return dy, -dx
        return {(origin[0] + rotate(dx, dy)[0], origin[1] + rotate(dx, dy)[1]) for dx, dy in offsets}


class ApproximateRealRangeTransformer:
    """Real raw range cells in the fixture's bottom-left field coordinates."""

    _directions = {"RIGHT", "DOWN", "LEFT", "UP"}

    def covered_tiles(
        self,
        *,
        origin: tuple[int, int],
        offsets: tuple[tuple[int, int], ...],
        direction: str,
    ) -> set[tuple[int, int]]:
        if direction not in self._directions:
            raise ValueError(f"Unsupported real direction: {direction}")
        def rotate(row: int, col: int) -> tuple[int, int]:
            if direction == "RIGHT": return col, row
            if direction == "DOWN": return row, -col
            if direction == "LEFT": return -col, -row
            return -row, col
        return {
            (origin[0] + rotate(row, col)[0], origin[1] + rotate(row, col)[1])
            for row, col in offsets
        }
    def _process_projectile_hit(self, state: SimulationState, source_id: str, target_id: str, *, raw_override: float | None = None) -> None:
        operator = state.deployed_operators.get(source_id)
        enemy = state.active_enemies.get(target_id)
        if operator is None:
            return
        if enemy is None:
            device = state.active_devices.get(target_id)
            if device is None:
                return
            self._emit(state, EventType.PROJECTILE_HIT, source=source_id, target=target_id)
            raw = self._effective_atk(operator) if raw_override is None else raw_override
            active_skill = self._skill(operator)
            damage_kind = (
                active_skill.effect.damage_type_override
                if operator.skill_active and active_skill and active_skill.effect.damage_type_override is not None
                else operator.damage_type
            )
            if damage_kind == "ARTS":
                damage = arts_damage(raw, device.magic_resistance,
                                     penetration_ratio=getattr(operator, "magic_resist_penetration", 0.0),
                                     penetration_flat=getattr(operator, "magic_resist_penetration_flat", 0.0))
                kind = "arts"
            else:
                damage = physical_damage(raw, device.defense,
                                         penetration_ratio=getattr(operator, "defense_penetration", 0.0),
                                         penetration_flat=getattr(operator, "defense_penetration_flat", 0.0))
                kind = "physical"
            self._apply_damage_to_device(state, target_id, source_id, damage, kind=kind)
            return
